import{esc,button,input,select,range}from'../phase4/ui.js';
import{number,value,groupCounts,sharedRemainder}from'./b16-model.js';
const f=(k,l,v)=>input(k,l,v,'autocomplete="off" spellcheck="false"'),btn=(a,l,d='')=>button('b16-'+a,l,d),on=v=>`aria-pressed="${v}"`,colors=['#dc9a62','#6da69b','#a998c9','#e6bd57'],units=[['pieces','颗'],['fen','分'],['g','克'],['cm','厘米'],['m','米'],['yuan','元'],['square','平方米']];
const relations=[['<','< 小于'],['=','= 等于'],['>','> 大于'],['≠','≠ 不等于'],['≤','≤ 小于或等于'],['≥','≥ 大于或等于']];
const p=(x,y,r,a)=>[x+r*Math.cos(a*Math.PI/180),y-r*Math.sin(a*Math.PI/180)],sector=(x,y,r,start,end)=>{const a=p(x,y,r,start),b=p(x,y,r,end);return`M${x},${y} L${a} A${r},${r} 0 ${end-start>180?1:0} 0 ${b} Z`;};
const svgButton=(a,i,label,body,extra='')=>`<g data-x="b16-${a}" data-index="${i}" role="button" tabindex="0" aria-label="${esc(label)}" ${extra}>${body}</g>`;
const strip=(d,selected,a='fraction',row='',cls='')=>`<div class="b16-strip ${cls}" style="--parts:${d}">${Array.from({length:d},(_,i)=>btn(a,selected.includes(i)?'●':'',`data-index="${i}" ${row?`data-row="${row}"`:''} aria-label="${row==='left'?'上':row==='right'?'下':''}第${i+1}份" ${on(selected.includes(i))}`)).join('')}</div>`;
function pie(d,selected,a='cell'){return`<svg viewBox="0 0 260 230" class="b16-pie" aria-label="一整个圆平均分成${d}份">${Array.from({length:d},(_,i)=>svgButton(a,i,`第${i+1}份`,`<path d="${sector(130,115,95,90+i*360/d,90+(i+1)*360/d)}" fill="${selected.includes(i)?colors[0]:'#f9f4e9'}" stroke="#705b41" stroke-width="2"/>`,on(selected.includes(i)))).join('')}</svg>`;}
function paper(t,m){const b=m.board;if(t.mode==='classify'){const c=t.cases[b.judgments.length];return c?`<div class="b16-piece-row">${c.map((v,i)=>`<span style="flex:${v}" aria-label="第${i+1}份占${v}格">${Array.from({length:v},()=>'<i></i>').join('')}</span>`).join('')}</div>`:'<div class="b16-note">这些分法都检查过了。</div>';}
 if(t.mode==='paint')return`<div class="b16-paint">${b.cells.map((c,i)=>btn('paint','',`data-index="${i}" aria-label="第${i+1}格" style="background:${c<0?'#f9f4e9':colors[c]}"`)).join('')}</div><div class="b16-saved">${b.saved.map((xs,i)=>`<div aria-label="第${i+1}种等面积分法">${xs.map(c=>`<i style="background:${colors[c]}"></i>`).join('')}</div>`).join('')}</div>`;
 if(t.shape==='circle')return pie(b.rows*b.cols,b.selected,'paper');return`<div class="b16-paper" style="--cols:${b.cols};--rows:${b.rows}">${Array.from({length:b.rows*b.cols},(_,i)=>btn('paper',b.selected.includes(i)?'●':'',`data-index="${i}" ${on(b.selected.includes(i))} aria-label="第${i+1}份"`)).join('')}</div>${b.folds.length?`<div class="b16-folds">${b.folds.map((v,i)=>`<span>${v==='x'?'左右':'上下'}对折 → ${2**(i+1)}份</span>`).join('')}</div>`:''}`;}
function groups(t,m){const b=m.board,counts=groupCounts(t,b);return`<div class="b16-token-pool">${b.groups.map((g,i)=>g===-1?btn('token','●',`data-index="${i}" aria-label="第${i+1}颗，移到当前组"`):'').join('')}</div><div class="b16-groups">${counts.map((n,g)=>`<section class="${b.taken.includes(g)?'taken':''}">${btn('group',`第${g+1}组`, `data-index="${g}" ${on(b.group===g)}`)}<div class="b16-tokens">${b.groups.map((v,i)=>v===g?btn('token','●',`data-index="${i}" aria-label="第${i+1}颗，在第${g+1}组"`):'').join('')}</div>${btn('take',b.taken.includes(g)?'已取这组':'取这一组',`data-index="${g}" ${on(b.taken.includes(g))}`)}</section>`).join('')}</div>`;}
function amount(t,m){return`<p class="b16-context">整条是 ${t.total} ${units.find(x=>x[0]===t.unit)?.[1]||''}</p>${strip(m.board.parts,m.board.taken,'take')}<div class="b16-brace">一个整体 ${t.total}</div>`;}
function walk(t,m){const b=m.board,max=Math.max(1,Math.ceil(t.n/t.d),t.axisMax||1,Math.ceil(b.steps.length/b.parts)),w=640,x=n=>30+n/max*580,den=b.parts;return`<svg class="b16-axis" viewBox="0 0 ${w} 180" role="img" aria-label="从0到${max}，每一整个分${den}段，已走${b.steps.length}步"><path d="M30 108H610" stroke="#554c40" stroke-width="3"/>${Array.from({length:max*den+1},(_,i)=>`<path d="M${x(i/den)} 100v${i%den===0?18:10}" stroke="#554c40"/>${i%den===0?`<text x="${x(i/den)}" y="143" text-anchor="middle">${i/den}</text>`:''}`).join('')}${b.steps.filter((j,i)=>(i+1)%(t.chunk||1)===0).map((j,k)=>{const i=k*(t.chunk||1);return`<path d="M${x(i/den)} 100Q${x((i+(t.chunk||1)/2)/den)} 55 ${x(j/den)} 100" fill="none" stroke="#c27c43" stroke-width="3"/>`;}).join('')}${t.halfBound?`<path d="M${x(.5)} 35V118" stroke="#9c8c74" stroke-dasharray="5 5"/><text x="${x(.5)}" y="165" text-anchor="middle">1/2</text>`:''}<circle cx="${x(b.steps.length/den)}" cy="108" r="8" fill="#4b8f80"/><text x="320" y="28" text-anchor="middle">每一步都是 1/${den}</text></svg>${t.buy?'<p class="b16-context">吃掉的量可以有零头，买来的披萨要按整个算。</p>':''}`;}
function sharing(t,m){const b=m.board,remain=t.wholes-b.rounds*t.people;return`<p class="b16-context">原来 ${t.wholes} 个整体 · 分给 ${t.people} 人</p><div class="b16-share-wholes">${!b.cut?Array.from({length:remain},(_,i)=>`<i aria-label="第${i+1}个剩余整体"></i>`).join(''):Array.from({length:remain},(_,row)=>`<div class="b16-cut-source"><small>余下第${row+1}个</small><div style="--parts:${t.people}">${Array.from({length:t.people},(_,col)=>{const i=row*t.people+col;return b.groups[i]===-1?btn('share-piece','',`data-index="${i}" aria-label="第${row+1}个剩余整体的第${col+1}片" style="background:${colors[row%4]}"`):`<span aria-label="已交给第${b.groups[i]+1}人">✓</span>`;}).join('')}</div></div>`).join('')}</div><div class="b16-groups">${Array.from({length:t.people},(_,g)=>`<section>${btn('person',`第${g+1}人`, `data-index="${g}" ${on(b.person===g)}`)}<div class="b16-share-holder"><b>${b.rounds}个整份</b>${b.groups.map((v,i)=>v===g?btn('share-piece',`1/${t.people}`,`data-index="${i}" aria-label="拿到的第${i+1}片" style="background:${colors[Math.floor(i/t.people)%4]}"`):'').join('')}</div></section>`).join('')}</div>`;}
function sameFraction(t,m){const b=m.board;if(!b.prediction)return`<div class="b16-predict"><div>${t.left[0]}/${t.left[1]}</div><span>同样大的整体</span><div>${t.right[0]}/${t.right[1]}</div></div>`;return`<div class="b16-fraction-pair"><span>取 ${t.left[0]}/${t.left[1]}</span>${strip(t.left[1],b.left,'fraction','left')}<span>取 ${t.right[0]}/${t.right[1]}</span>${strip(t.right[1],b.right,'fraction','right')}${b.overlay?`<div class="b16-overlay"><i style="width:${b.left.length/t.left[1]*100}%"></i><i style="width:${b.right.length/t.right[1]*100}%"></i>${b.refine?Array.from({length:b.refine+1},(_,i)=>`<em style="left:${i/b.refine*100}%"></em>`).join(''):''}</div>`:''}</div>`;}
function mixed(t,m){const b=m.board,x=n=>40+(n-t.min)/(t.max-t.min)*570;return`<div class="b16-cards">${t.cards.map((v,i)=>btn('select',v,`data-index="${i}" ${on(b.selected===i)}`)).join('')}</div><svg class="b16-axis" viewBox="0 0 660 170" role="img" aria-label="所有卡片共用的数轴"><path d="M40 95H610" stroke="#554c40" stroke-width="3"/>${Array.from({length:t.max-t.min+1},(_,i)=>`<path d="M${x(t.min+i)} 88v16" stroke="#554c40"/><text x="${x(t.min+i)}" y="130" text-anchor="middle">${t.min+i}</text>`).join('')}${Object.entries(b.placements).map(([i,n])=>`<circle cx="${x(n)}" cy="${65-Number(i)%3*19}" r="6" fill="${colors[Number(i)%4]}"/><path d="M${x(n)} ${70-Number(i)%3*19}V95" stroke="${colors[Number(i)%4]}"/><text x="${x(n)+10}" y="${68-Number(i)%3*19}" font-size="14">${esc(t.cards[i])}</text>`).join('')}</svg><div class="b16-sort">${t.cards.map((v,i)=>btn('order',v,`data-index="${i}" ${on(b.ordered.includes(i))}`)).join('')}<p>从小到大：${b.ordered.map(i=>t.cards[i]).join('　→　')||'点卡片排一排'}</p></div>`;}
function digits(t,m){const b=m.board,c=t.cases[b.index];return`<div class="b16-cards">${t.cases.map((c,i)=>btn('digit',`看第${i+1}张`, `data-index="${i}" ${on(i===b.index)}`)).join('')}</div><div class="b16-numeral">${Array.from(c.raw).map((v,i)=>i===c.at?`<mark>${v}</mark>`:esc(v)).join('')}</div><p class="b16-context">亮起的这个数字，在这里表示多少？</p><div class="b16-checks">${b.records.map(i=>`<span>✓ 第${i+1}张</span>`).join('')}</div>`;}
function talk(t,m){const c=t.cases[m.board.records.length];return c?`<div class="b16-message">${esc(c.label)}</div>`:'<div class="b16-note">这些记录都说清楚了。</div>';}
function graph(t,m){const b=m.board,x=v=>65+v/t.maxX*510,y=v=>280-v/t.maxY*230,pts=t.read?t.data:[];return`<div class="b16-graph-layout"><table><thead><tr><th>${esc(t.xLabel)}</th><th>${esc(t.yLabel)}</th></tr></thead><tbody>${t.data.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table><svg viewBox="0 0 660 345" class="b16-graph" role="img" aria-label="横轴${esc(t.xLabel)}，纵轴${esc(t.yLabel)}"><path d="M65 30V280H590" fill="none" stroke="#554c40" stroke-width="2"/>${Array.from({length:t.maxX+1},(_,i)=>`<path d="M${x(i)} 50V280" stroke="#dfd5c4"/><text x="${x(i)}" y="304" text-anchor="middle">${i}</text>`).join('')}${Array.from({length:t.maxY+1},(_,i)=>`<path d="M65 ${y(i)}H575" stroke="#dfd5c4"/><text x="48" y="${y(i)+5}" text-anchor="end">${i}</text>`).join('')}${t.line&&b.points.length>1?`<polyline points="${[...b.points].sort((a,b)=>a[0]-b[0]).map(([a,b])=>`${x(a)},${y(b)}`).join(' ')}" fill="none" stroke="#6a9f94" stroke-width="3"/>`:''}${b.points.map(([a,b])=>`<circle cx="${x(a)}" cy="${y(b)}" r="7" fill="#c17b47"/>`).join('')}<text x="315" y="338" text-anchor="middle">${esc(t.xLabel)}</text><text x="65" y="20">${esc(t.yLabel)}</text></svg></div>${t.read?`<div class="b16-cards">${t.data.map((p,i)=>btn('readpoint',`读第${p[0]}次`, `data-index="${i}" ${on(b.selected.includes(i))}`)).join('')}</div>`:''}`;}
function repair(t,m){const b=m.board,ones=t.a*(t.b%10),tens=t.a*Math.floor(t.b/10),row=tens*10**b.shift;return`<div class="b16-written"><div>${t.a}</div><div>× ${t.b}</div><hr><div>${ones}</div><div class="b16-shift-row">${row}</div><hr><div>${ones+row}</div></div><p class="b16-context">被移动的这一行：${t.a} × ${Math.floor(t.b/10)} 个十</p>`;}
function angles(t,m){const b=m.board,A=t.angles[0]*Math.PI/180,B=t.angles[1]*Math.PI/180,C=t.angles[2]*Math.PI/180,vertices=[[60,205],[220,205],[60+160*Math.sin(B)/Math.sin(C)*Math.cos(A),205-160*Math.sin(B)/Math.sin(C)*Math.sin(A)]],starts=[0,180-t.angles[1],180+t.angles[0]];return`<div class="b16-angle-scene"><svg viewBox="0 0 320 245" aria-label="三角形的三个角"><polygon points="${vertices.map(p=>p.join(',')).join(' ')}" fill="#f6eddc" stroke="#6c5c45" stroke-width="2"/>${vertices.map(([x,y],i)=>{const start=i===2?180+t.angles[0]:starts[i];return svgButton('angle',i,`取${'ABC'[i]}角`,`<path d="${sector(x,y,37,start,start+t.angles[i])}" fill="${colors[i]}" stroke="#65543e"/><text x="${x+(i===1?-15:15)}" y="${y+(i===2?28:-12)}" text-anchor="middle">${'ABC'[i]}</text>`,on(b.selected===i));}).join('')}</svg><svg viewBox="0 0 400 245" aria-label="把角拼到同一条直线上"><path d="M25 210H375" stroke="#6c5c45" stroke-width="3"/>${b.placed.map(q=>`<path d="${sector(200,210,150,q.start,q.end)}" fill="${colors[q.index]}" fill-opacity=".75" stroke="#5d503f" stroke-width="2"/>`).join('')}<circle cx="200" cy="210" r="5" fill="#554c40"/><text x="365" y="235">0°</text><text x="15" y="235">180°</text></svg></div>${b.selected!==null?`<p class="b16-context">现在搬 ${'ABC'[b.selected]} 角，起边朝 ${esc(m.rotation)}°</p>`:''}<div class="b16-chain">${[['original','取出原来的三个角'],['together','同一点，不重叠、不留缝'],['straight','拼成一条直线']].map(([v,l])=>btn('chain',l,`data-value="${v}" ${on(b.chain.includes(v))}`)).join('')}<p>${b.chain.map(v=>({original:'原来的角',together:'无缝拼合',straight:'成为直线'}[v])).join(' → ')}</p></div>`;}
function algebra(t,m){const b=m.board,scale=560/t.total,part=(t.total-t.fixed)/t.count;return`<div class="b16-algebra"><div class="b16-algebra-line">${Array.from({length:b.count},()=>`<i style="width:${part*scale}px">?</i>`).join('')}${!b.removed&&b.fixed?`<i class="fixed" style="width:${b.fixed*scale}px">${b.fixed}</i>`:''}</div><div class="b16-algebra-line"><i class="total" style="width:${(b.removed?t.total-b.fixed:t.total)*scale}px">${b.removed?t.total-b.fixed:t.total}</i></div>${b.divided?`<p>每份：${(t.total-b.fixed)/b.count}</p>`:''}</div>`;}
function fdp(t,m){const b=m.board;return`<div class="b16-fdp">${t.d===100?`<div class="b16-hundred"><div class="b16-grid100">${Array.from({length:100},(_,i)=>btn('cell','',`data-index="${i}" aria-label="第${i+1}小格" ${on(b.selected.includes(i))}`)).join('')}</div><div class="b16-row-buttons">${Array.from({length:10},(_,i)=>btn('row','↔',`data-index="${i}" aria-label="涂或擦第${i+1}行"`)).join('')}</div></div>`:pie(t.d,b.selected)}${b.seen.includes('line')?`<div class="b16-position-line"><i style="left:${b.selected.length/t.d*100}%"></i><span>0</span><span>1</span></div>`:''}${b.seen.includes('pie')&&t.d===100?`<svg viewBox="0 0 240 230" class="b16-pie" role="img" aria-label="同一部分换到圆中"><circle cx="120" cy="115" r="90" fill="#f9f4e9" stroke="#705b41"/>${b.selected.length===t.d?`<circle cx="120" cy="115" r="90" fill="${colors[0]}"/>`:`<path d="${sector(120,115,90,90,90+b.selected.length/t.d*360)}" fill="${colors[0]}"/>`}</svg>`:''}</div>`;}
export function visual(t,m){switch(t.type){case'x-paperlab':return paper(t,m);case'x-portiongroups':return groups(t,m);case'x-portionbar':return amount(t,m);case'x-unitwalk':return walk(t,m);case'x-wholeshare':return sharing(t,m);case'x-samefraction':return sameFraction(t,m);case'x-mixedaxis':return mixed(t,m);case'x-digitlens':return digits(t,m);case'x-fractiontalk':return talk(t,m);case'x-graphpoints':return graph(t,m);case'x-rowrepair':return repair(t,m);case'x-anglejoin':return angles(t,m);case'x-algebrabar':return algebra(t,m);case'x-fdpboard':return fdp(t,m);}}
export function controls(t,m){const b=m.board;switch(t.type){
 case'x-paperlab':if(t.mode==='classify')return b.judgments.length<t.cases.length?select('choice',t.writeName?'这些部分一样大吗':`这些是${t.d}个相等的份吗`,m.choice,[['yes','是'],['no','不是']])+(t.writeName?f('answer','相等时，每小份占整个的几分之几',m.answer):'')+btn('judge','检查这个分法'):'';if(t.mode==='paint')return select('color','现在涂哪一种颜色',m.color,colors.map((_,i)=>[i,['橙','绿','紫','黄'][i]]))+btn('save','留下这一种分法')+(b.saved.length>=2?f('answer','每种颜色占整个的几分之几',m.answer):'');return(t.mode==='fold'?btn('fold','左右对折',`data-value="x"`)+btn('fold','上下对折',`data-value="y"`):f('rows','分几行',m.rows)+f('cols',t.shape==='circle'?'从中心分几份':'分几列',m.cols)+btn('partition','照这样分开'))+(b.rows*b.cols>1?f('answer','涂出的量怎样写（如1/3）',m.answer):'');
 case'x-portiongroups':return b.groups.every(g=>g>=0)?f('per','一样多的一组有几颗',m.per)+f('answer','选中的几组一共有多少',m.answer)+(t.name?f('num','选了几个单位份',m.num)+f('den','整个有几个这样的单位份',m.den):'')+(t.equation?f('equation','把这次分与取写成等式',m.equation):''):'';
 case'x-portionbar':return f('parts','把整个分成几等份',m.parts)+btn('bar','平均分开')+(b.built?f('per','一份是多少',m.per)+f('answer','取出的部分一共多少',m.answer)+select('unit','答案的单位',m.unit,units)+f('equation','把分与取写成等式',m.equation):'');
 case'x-unitwalk':return f('parts','每个0到1分成几等份',m.parts)+btn('partition','留下等长间隔')+btn('walk',t.chunk?'接上这一次的'+t.chunk+'小份':'往前走一小份')+btn('walk-back','退回一小份')+(b.steps.length?f('answer','终点是哪个数（可写分数）',m.answer)+(t.copies?f('copies','一共用了几个小份',m.copies)+f('equation','把相同小份用 + 接起来',m.equation):'')+(t.whole?f('whole','其中有几个完整的1',m.whole)+f('remainder','还多几分之几',m.remainder):'')+(t.decimal?f('decimal','同一点换成小数',m.decimal):'')+(t.bounds?f('left','左边相邻的整数',m.left)+f('right','右边相邻的整数',m.right):'')+(t.buy?f('total','按整个买，至少买几个',m.total):'')+(t.chunk?f('equation','用乘法记录每份与总份数',m.equation):'')+(t.halfBound?select('relation','这个点与1/2相比',m.relation,relations.slice(0,3)):''):'');
 case'x-wholeshare':return !b.cut?btn('round','每人分一个完整的')+btn('cut-wholes','余下的每个继续平均切开'):(b.groups.every(g=>g>=0)?f('whole','每人拿到几个完整的',m.whole)+f('remainder','每人再拿到几分之几',m.remainder)+f('answer','每人合起来是多少',m.answer)+f('equation','用除法与分数记录（可用÷和/）',m.equation)+f('total','每人的量乘人数，怎样乘回原来的总量',m.total):'');
 case'x-samefraction':return !b.prediction?select('prediction','先猜上面的量与下面相比',m.prediction,relations.slice(0,3))+btn('predict','留下预测，再动手'):btn('overlay','把两边叠起来比较')+(t.common?f('parts','都继续分成多少小份',m.parts)+btn('refine','画出共同的小格'):'')+(b.overlay?(t.common&&b.refine?f('left','上边换成共同的小份，写分数',m.left)+f('right','下边换成共同的小份，写分数',m.right):'')+select('relation','现在比较上面的量与下面',m.relation,relations.slice(0,3))+select('reason','这次比较固定了什么',m.reason,[['same-whole','两边整体一样大'],['any-whole','整体可以随便换大小']]):'');
 case'x-mixedaxis':{const q=t.statements?.[b.symbols.length];return f('position',`把 ${t.cards[b.selected]} 放在数轴上的哪个位置`,m.position)+btn('place','放到这个位置')+(q?`<span class="b16-statement">${esc(q.a)}　?　${esc(q.b)}（${esc(q.word)}）</span>`+select('relation','选择符合这句话的符号',m.relation,relations)+btn('symbol','留下这句比较'):'');}
 case'x-digitlens':return f('answer','高亮数字表示的量',m.answer)+btn('digit-save','留下这一张的读法');
 case'x-fractiontalk':{const c=t.cases[b.records.length];if(!c)return'';return(c.kind==='vocab'?select('top','上面的数叫什么',m.top,[['numerator','分子'],['denominator','分母']])+select('bottom','下面的数叫什么',m.bottom,[['numerator','分子'],['denominator','分母']])+select('word','同一个量的不同分数写法叫什么',m.word,[['equivalent','等值'],['different','不同的量']]):c.kind==='symbol'?select('relation','选相符的符号',m.relation,relations):f('answer','数值写在这里',m.answer)+select('unit','带上单位',m.unit,units))+btn('talk','让这句话说清楚');}
 case'x-graphpoints':return f('x',t.xLabel,m.x)+f('y',t.yLabel,m.y)+btn('plot','把这一点放进图中')+(b.points.length===t.data.length?f('answer',t.read?'两次的量相差多少':'每增加横轴的一份，纵轴增加多少',m.answer)+(t.read?f('equation','把相差多少写成等式',m.equation):select('reason','你看到的关系',m.reason,[['per-x','横轴每多1，纵轴增加同样的量'],['sum','把两个坐标相加就是关系']])):'');
 case'x-rowrepair':return select('shift','第二行应该放在哪一位开始',m.shift,[['0','个位'],['1','十位'],['2','百位']])+btn('shift','移动这一行')+f('answer','修好后总数是多少',m.answer)+select('reason','为什么要这样放',m.reason,[['tens-row','这一行乘的是几十，单位是十'],['more','为了让最后结果更大']]);
 case'x-anglejoin':return b.selected!==null?range('rotation','搬来后，起边朝几度',m.rotation,0,180,15)+btn('rotate-place','把选中的角放到这里')+(b.placed.length===3?f('answer','拼成的角一共多少度',m.answer):''):'';
 case'x-algebrabar':return f('count','相同的未知量有几份',m.count)+f('fixed','另外多的一块是多少',m.fixed)+btn('algebra','先把这段关系摆出来')+(b.built?(!b.removed?f('result','两边拿走额外的一块，各剩多少',m.result)+btn('remove','两边一起拿走'):!b.divided?f('result','再把两边平均分，每份多少',m.result)+btn('divide','两边一起平均分'):f('answer','原来一份的未知数是多少',m.answer)+f('equation','用n写出原来的等量关系',m.equation)):'');
 case'x-fdpboard':return(t.views||[]).map(v=>btn('view',{grid:'看方格',pie:'换成圆图',line:'放到0与1之间'}[v],`data-value="${v}"`)).join('')+(b.selected.length?f('num','用分数写，上面的数',m.num)+f('den','用分数写，下面的数',m.den)+f('decimal','同一个量的小数',m.decimal)+f('percent','同一个量是百分之几',m.percent):'');
 }return'';}
export const render=(t,m)=>`<section class="b16-work"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p class="b16-issue" role="status">${esc(m.issue)}</p>`:''}${btn('reset','重新摆，保留之前的尝试')}</div></section>`;
